use strict;
use warnings FATAL => 'all';
use PostgreSQL::Test::Cluster;
use PostgreSQL::Test::Utils;
use Test::More;
my $node=PostgreSQL::Test::Cluster->new('revision_views');
$node->init(extra=>['--encoding=UTF8','--locale=C']);$node->append_conf('postgresql.conf',"default_table_access_method='dolt_prolly_table'\n");$node->start;
sub sql {return $node->safe_psql('postgres',$_[0]);}
sql(q{CREATE TABLE t(id int PRIMARY KEY,v text) USING dolt_prolly_table; SELECT dolt_commit('-Am','base'); SELECT dolt_checkout('-b','other'); ALTER TABLE t ADD COLUMN extra int; CREATE TABLE other_only(x int PRIMARY KEY); SELECT dolt_commit('-Am','other')});
my $cols=q{SELECT column_name FROM information_schema.columns AS OF 'other' WHERE table_schema='public' AND table_name='t' ORDER BY ordinal_position};
is(sql($cols),"id\nv\nextra",'historical information schema columns');
is(sql(q{SELECT tablename FROM pg_tables AS OF 'other' WHERE schemaname='public' ORDER BY tablename}),"other_only\nt",'historical pg_tables');
is(sql(q{SELECT indexname FROM pg_indexes AS OF 'other' WHERE schemaname='public' AND tablename='t'}),'t_pkey','historical index deparser');
is(sql(q{SELECT a.column_name,b.column_name FROM information_schema.columns AS OF 'main' a CROSS JOIN information_schema.columns AS OF 'other' b WHERE a.table_name='t' AND a.column_name='v' AND b.table_name='t' AND b.column_name='extra'}),'v|extra','two view contexts in one statement');
is(sql(q{SELECT column_name FROM "postgres/other".information_schema.columns WHERE table_name='t' ORDER BY ordinal_position}),"id\nv\nextra",'branch-qualified view');
my $s=$node->background_psql('postgres');
$s->query_safe('PREPARE p AS '.$cols);
is($s->query_safe('EXECUTE p'),"id\nv\nextra",'prepared historical view');
$s->query_safe(q{SELECT dolt_checkout('other')});
is($s->query_safe(q{SELECT column_name FROM information_schema.columns AS OF 'main' WHERE table_name='t' ORDER BY ordinal_position}),"id\nv",'qualifier overrides selected branch');
is($s->query_safe('EXECUTE p'),"id\nv\nextra",'prepared context survives checkout');
is(sql(q{SELECT table_name FROM information_schema.constraint_table_usage AS OF 'other' WHERE table_schema='public' ORDER BY table_name}),"other_only\nt",'nested catalog view expansion retains context');
is(sql(q{SET debug_copy_parse_plan_trees=on; SET debug_write_read_parse_plan_trees=on; SELECT tablename FROM pg_tables AS OF 'other' WHERE schemaname='public' ORDER BY tablename}),"other_only\nt",'context survives query-tree copy and serialization');
is(sql(q{BEGIN READ ONLY; SELECT tablename FROM pg_tables AS OF 'other' WHERE schemaname='public' ORDER BY tablename; COMMIT}),"other_only\nt",'read-only historical view needs no materialization');
$s->query_safe(q{BEGIN; DECLARE c CURSOR FOR SELECT column_name FROM "postgres/other".information_schema.columns WHERE table_name='t' ORDER BY ordinal_position});
is($s->query_safe('FETCH 1 FROM c'),'id','cursor pins view context');
sql(q{SELECT dolt_checkout('other'); ALTER TABLE t ADD COLUMN later int; SELECT dolt_commit('-Am','later')});
is($s->query_safe('FETCH ALL FROM c'),"v\nextra",'open cursor retains old view after HEAD changes');
$s->query_safe('COMMIT');
is($s->query_safe('EXECUTE p'),"id\nv\nextra\nlater",'prepared symbolic revision rebinds after HEAD changes');
$s->quit;$node->stop;$node->start;
is(sql($cols),"id\nv\nextra\nlater",'cold historical view binding');
$node->stop;done_testing();
